# simulate until time 259
def process(threshold):
    running={}
    for r in rows:
        t=int(r[0])
        if t>threshold:
            break
        event=r[7]
        task=r[1]
        machine=r[8]
        if event=='start':
            running[task]=machine
        elif event in ('finish','evict','fail'):
            running.pop(task,None)
    return running
